#ifndef ANNC_LIB_TARGET_AARCH64_GEMM_GEMPLANNER_H
#define ANNC_LIB_TARGET_AARCH64_GEMM_GEMPLANNER_H

#include <cstdint>
#include <string>

namespace annc::aarch64::gemm {

struct GemmPlannerCacheTile {
  std::int64_t mc;
  std::int64_t nc;
  std::int64_t kc;
};

struct GemmPlannerCostModel {
  // Effective kernel memory costs. These describe the traffic generated by
  // the selected kernel path, not literal cache or DRAM latency.
  double load_cycles_per_byte;
  double store_cycles_per_byte;
  // GEMM and GEMV-AB have different instruction schedules and therefore use
  // different effective compute coefficients.
  double compute_cycle_scale;
  double gemv_compute_cycle_scale;
  double microkernel_call_cycles;
  // Aggregate generated PackB cost. Direct and prepacked RHS paths do not
  // charge this term.
  double pack_cycles_per_byte;
  double pack_call_cycles;
};

struct GemmPlannerConfig {
  std::int64_t m;
  std::int64_t n;
  std::int64_t k;
  std::int64_t max_threads;
  std::int64_t microkernel_m;
  std::int64_t microkernel_n;
  std::int64_t packet_size;
  // Packed-B storage alignment in elements. NEON uses one vector; the SVE
  // packer uses four predicated vector streams per panel.
  std::int64_t rhs_memory_alignment;
  // True only when lowering generates a runtime PackB call for this task.
  // Direct and prepacked RHS representations set this to false.
  bool needs_runtime_pack;
  // GEMM vectorizes output columns. The dedicated GEMV-AB family instead
  // vectorizes the K reduction and therefore has a different instruction
  // count even though it uses the same planner entry point.
  bool vectorize_reduction;
  // Keep operand and result widths separate.  They are all four bytes for the
  // current f32 ABI, but mixed-precision kernels must not reuse one scalar
  // width for cache occupancy, input traffic, and output traffic.
  std::int64_t lhs_scalar_bytes;
  std::int64_t rhs_scalar_bytes;
  std::int64_t output_scalar_bytes;
  GemmPlannerCostModel cost_model;
  GemmPlannerCacheTile cache_tile{1, 1, 1};
};

struct GemmPlanningResult {
  std::int64_t thread_count;
  std::int64_t tasks_m;
  std::int64_t tasks_n;
  bool shard_by_columns;
};

// Sixteen f32 columns = one 64-byte output-row cache line; N tasks truncate
// to this granularity so neighbors stay off shared output cache lines.
inline constexpr std::int64_t kGemmTaskSplitAlignment = 16;

// Truncation-aligned split: non-final tasks get floor(dimension/tasks)
// truncated down to the alignment; the final task absorbs the remainder.
// Single source of truth shared by the planner cost model and the
// thread-tiling materializer.
struct GemmTaskSplit {
  std::int64_t base;  // Extent of every non-final task.
  std::int64_t tail;  // Extent of the final task (never smaller than base).
};

inline bool splitGemmTaskRange(std::int64_t dimension, std::int64_t tasks,
                               std::int64_t alignment, GemmTaskSplit &split) {
  if (dimension <= 0 || tasks <= 0 || alignment <= 0) return false;
  if (tasks == 1) {
    split = GemmTaskSplit{dimension, dimension};
    return true;
  }
  const std::int64_t quotient = dimension / tasks;
  const std::int64_t base = quotient - quotient % alignment;
  if (base <= 0) return false;
  split = GemmTaskSplit{base, dimension - (tasks - 1) * base};
  return true;
}

// Selects a cost-model-based thread count and microkernel-aligned static
// grid. Cache and kernel tiles are the tuning-config values consumed by the
// subsequent lowering; the planner does not derive a second block plan.
bool planGemm(const GemmPlannerConfig &config, GemmPlanningResult &result,
              std::string &error);

}  // namespace annc::aarch64::gemm

#endif  // ANNC_LIB_TARGET_AARCH64_GEMM_GEMPLANNER_H
